learn=[('Predict the six-stage order', 'Read the documented order: PreToolUse hooks, deny rules, ask rules, permission mode, allow rules and canUseTool. Some stages resolve a call before later checks. The app shows this as reference guidance, not a fabricated SDK internal trace.'), ('Observe hooks before later checks', 'A hook deny blocks the classroom Write even when Write is pre-approved. In a separate experiment, hook allow passes a bounded file-removal attempt onward but does not override its matching deny rule.'), ('Compare deny and ask against bypass', 'A scoped Bash(rm *) deny blocks the attempted disposable-fixture removal in bypassPermissions. A bare Write ask rule sends a write to the host callback even in bypass mode. The callback allows only the fixed classroom output.'), ('Understand callback shadowing', 'An allow rule or acceptEdits can approve a Write before canUseTool, so the callback count remains zero. The TypeScript SDK emits CLAUDE_SDK_CAN_USE_TOOL_SHADOWED for some configurations; acceptEdits does not trigger that construction-time warning.'), ('Distinguish fallback denial from dontAsk', 'With default mode and no matching rule, the Write reaches a callback that denies it. In dontAsk, the unresolved Write is denied without invoking the callback. Both keep the file absent, but their traces differ.'), ('Verify tool outcomes independently', 'Inspect actual PreToolUse and PostToolUse events, native tool results, callback invocations and host file checks. A denied tool may be followed by a successful final model response. A model statement alone does not prove that a file changed.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3127\n# Windows if needed: CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Install Node.js 24 or later and Git for Windows if the SDK needs Git Bash. Use an Anthropic API account with credit and model access. Python is needed only to regenerate student HTML.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter this application, install locked dependencies and preserve an existing .env. Enter your own model key privately. No GitHub token or Managed Agents resource IDs are required.', 'cd .\\agent-sdk\\lesson27-permission-pipeline\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the application', 'Keep the terminal open and use the printed URL. Experiments create and clean up fresh temporary classroom directories; your course source is not the agent workspace.', 'npm start\n# http://127.0.0.1:3127'), ('Predict hook, deny and ask outcomes', 'Choose a mode and predict execute or block. Run the experiment and inspect actual hook decisions, callback counts and file evidence. The bypass modes are bounded classroom demonstrations.', 'npm run sample:env -- hook-deny\nnpm run sample:env -- deny-bypass\nnpm run sample:env -- ask-bypass'), ('Compare automatic approval and callback fallback', 'Compare Allow rule with Callback deny. Both use default mode, but the allow rule resolves Write before the callback. Callback deny reaches the host fallback and leaves the file absent.', 'npm run sample:env -- allow-rule\nnpm run sample:env -- callback-deny'), ('Compare acceptEdits with dontAsk', 'acceptEdits approves the classroom Write without a callback. dontAsk denies an unresolved Write without a callback. Use PostToolUse and host file checks to distinguish their outcomes.', 'npm run sample:env -- accept-edits\nnpm run sample:env -- dont-ask\nnpm test')]
specs=[('Validate the prediction and experiment', 'src/permissions.ts', 'export function validateConfig', 'Only fixed classroom modes and execute/block predictions are accepted. Browser input cannot supply arbitrary tool commands, paths or permission rules.', 0, 1, 7), ('Prepare a disposable workspace', 'src/workspace.ts', 'const root =', 'A verified temporary run directory contains a protected fixture and an initially absent output. Agent operations do not use the lesson repository as their working directory.', 1, 4, 8), ('Configure scoped rules and mode', 'src/agent.ts', 'allowedTools: s.allowed,', 'Pass the chosen allow/deny rules, ask settings and permission mode into the real SDK. Bare deny names remove tools; this lesson uses a scoped Bash deny so the attempt remains observable.', 1, 2, 7), ('Guard the exact classroom operation', 'src/permissions.ts', 'const target =', 'The host permits only exact fixture-removal command forms or the fixed output write. This boundary narrows the teaching exercise; it is not presented as an operating-system sandbox.', 1, 1, 7), ('Record the PreToolUse decision', 'src/agent.ts', 'const decision =', 'The hook denies the hook experiment, allows the bounded deny-rule experiment onward, or returns no decision for the remaining allowed classroom operation.', 2, 1, 8), ('Keep deny stronger than bypass', 'src/permissions.ts', '"deny-bypass": {', 'The reference configuration combines a scoped Bash deny, a matching allow and bypass mode. The live evidence must show a hook allow, no successful removal and an unchanged fixture.', 2, 2, 8), ('Force the ask-rule callback', 'src/agent.ts', 'canUseTool: async', 'The Write ask rule routes bypass-mode Write to this host callback. Only the fixed ask-bypass operation is allowed here; unresolved calls in other modes are denied.', 2, 1, 8), ('Start the real model query', 'src/agent.ts', 'const run = query', 'The host supplies one bounded task and the fresh workspace. The model must make the actual tool attempt and accept denial without another approach.', 1, 2, 7), ('Capture actual tool requests', 'src/agent.ts', 'if (block.type === "tool_use")', 'Record real tool-use IDs, names and inputs. A tool request is an attempt, not proof that the permission pipeline allowed it to execute.', 2, 1, 4), ('Capture native denial feedback', 'src/agent.ts', 'if (block.is_error)', 'Native tool-result errors remain visible. A permission rejection is distinct from a crashed query, and the model may still finish with a successful explanation.', 2, 0, 7), ('Observe successful completion', 'src/agent.ts', 'completed.push(input.tool_name);', 'PostToolUse marks successful tool completion. Compare it with callback counts to see whether an earlier permission stage approved the operation.', 2, 1, 7), ('Verify files independently', 'src/workspace.ts', 'fileCreated: fileContents', 'The host compares actual output content and protected fixture state before cleanup. This check does not rely on the model claiming success.', 4, 1, 4), ('Render prediction feedback', 'src/client.ts', '$("verdict").textContent =', 'Render the actual outcome and compare it with the student prediction. Keep reference expectations separate from recorded hook and callback events.', 1, 0, 3)]
document('/','Permissions. <em>Trace the decision.</em>','Predict actual tool outcomes, observe the SDK and verify disposable files.','<div class="flow"><div><b>01 · Predict</b><p>Choose execute or block</p></div><span>→</span><div><b>02 · Trace</b><p>Actual hooks and callback</p></div><span>→</span><div><b>03 · Verify</b><p>Native results and file evidence</p></div></div><section class="panel" id="controls"><h2>Explore permission evaluation</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Permission experiment</label><select id="mode"><option value="hook-deny">Hook deny · pre-approved Write is blocked</option><option value="deny-bypass">Deny rule · wins over bypass and hook allow</option><option value="ask-bypass">Ask rule · callback runs even in bypass</option><option value="allow-rule">Allow rule · callback is skipped</option><option value="callback-deny">Default fallback · callback denies</option><option value="accept-edits">acceptEdits · Write is auto-approved</option><option value="dont-ask">dontAsk · unresolved Write is denied</option></select><label for="prediction">Predict the tool outcome</label><select id="prediction"><option value="block">Block</option><option value="execute">Execute</option></select><button id="run" class="primary" disabled>Run permission experiment →</button><p class="meta">Each run uses a fresh disposable classroom directory. The host permits only the fixed output write or the bounded fixture-removal attempt. Callback decisions are programmed classroom policy, not a human approval prompt.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Reference expectations are labelled separately from observed callbacks, completed tools and file changes.</p></section></div><section class="step" id="pipeline-panel"><h2>Documented evaluation order · reference</h2><p>This is an explanatory reference. The SDK does not emit a public event for every internal rule check. Observe the actual events below.</p><div class="grid"><article class="card"><h3>1 · Hooks</h3><p>Deny outright or pass onward. Hook allow does not bypass deny and ask rules.</p></article><article class="card"><h3>2 · Deny rules</h3><p>A matching scoped deny blocks the call, including in bypassPermissions.</p></article><article class="card"><h3>3 · Ask rules</h3><p>A matching ask routes to canUseTool. In dontAsk, prompting is denied.</p></article><article class="card"><h3>4 · Permission mode</h3><p>bypassPermissions and acceptEdits can resolve eligible operations. Plan gates writes.</p></article><article class="card"><h3>5 · Allow rules</h3><p>Matching rules and safe built-in checks can approve calls before the callback.</p></article><article class="card"><h3>6 · canUseTool</h3><p>The callback decides unresolved calls; dontAsk denies instead of prompting.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual permission configuration</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>Rules, mode and classroom callback policy. No secrets or real .env content is served.</p></section><section class="step" id="discovery-panel"><h2>Actual initialization snapshot</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>The available tool list is distinct from permission to execute a specific call.</p></section><section class="step" id="trace-panel"><h2>Actual hooks and callback invocations</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>Pass means the classroom hook returned no permission decision. Post means the SDK reported successful tool completion. No unobserved internal stages are inserted.</p></section><section class="step" id="native-panel"><h2>Actual native tool results</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>Denied tools return visible feedback. A later success result from the model does not turn a denied operation into an executed one.</p></section><section class="step" id="warning-panel"><h2>Actual SDK warning codes</h2><pre class="json-view"><code id="warnings" class="language-json">{}</code></pre><p>Warnings describe potentially shadowed callback configuration. Their presence is not proof of a specific permission outcome; their absence does not prove the callback ran.</p></section><section class="step" id="evidence-panel"><h2>Independent execution and file evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Host file checks verify the result separately from model text. The protected classroom fixture must remain unchanged.</p></section><section class="step" id="comparison-panel"><h2>Compare predictions with actual outcomes</h2><p id="verdict">Choose a prediction before each run.</p><div class="table"><table><thead><tr><th>Mode</th><th>Reference stage</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Completed</th><th>Fixture</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand the documented order and compare actual hook, callback and file evidence.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. A zero callback count does not by itself prove approval. Check native errors, completion and host file evidence. Warnings do not cover every shadowing configuration.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK pipeline','Host callback','Lab files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 27 · Predict → trace → verify permissions</text>']
