for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">This diagram groups configuration and runtime observations across alternative experiments. Internal permission checks are documented reference, not invented telemetry.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen permission-evaluation workflow steps"></div>'+walk)

reference=[('Documented pipeline versus observable evidence', 'The six-step diagram is reference guidance. Public events expose hooks, callback invocations, native results and completion, not every internal rule comparison. Reference stage labels describe the configured experiment and do not pretend to be internal SDK telemetry.'), ('Ask is distinct from hook allow', 'A hook allow does not skip deny or ask rules. The ask experiment uses a bare Write ask rule and a programmed callback that approves only the bounded classroom output. It is not a human approval UI.'), ('Bare versus scoped deny', 'A bare disallowedTools name removes the tool definition, preventing that attempt. Bash(rm *) keeps Bash available and blocks matching commands as written. It is not a universal detector of every command spelling. The host guard independently restricts this lab to one disposable target.'), ('File rule details', 'Bare Write ask and allow entries are used here. For path-scoped rules governing built-in writes, current docs specify Edit(path), including Write and NotebookEdit. Do not assume Write(path) works the same way.'), ('Modes and safe built-ins', 'acceptEdits auto-approves eligible file operations; default can approve safe reads or read-only shell commands without a callback. allowedTools is pre-approval, not a complete tool inventory or universal whitelist. This lab narrows available tools explicitly.'), ('Warnings are partial diagnostics', 'The SDK can warn for bypass mode or bare allow entries. acceptEdits can skip the callback without that construction-time warning. Matching rules from settings may also affect execution without being visible to the warning check.'), ('Plan and critical-path exceptions', 'Plan mode routes write operations for approval regardless of allow rules. Some user-interaction tools and recognized critical-path removals are not automatically approved. This application never tests critical-path removal, production pushes or unrelated shell operations.'), ('Cost and isolation', 'Each real model query uses an SDK budget threshold of $0.25, not a prepaid cap. A fresh bounded workspace and exact operation guard constrain the demonstration; SDK permission settings alone are not an operating-system sandbox. Credentials and all teaching media remain outside Git.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 27 · How permissions are evaluated\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson27-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson27-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson27-permission-pipeline`. Open http://127.0.0.1:3127 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK permissions documentation](https://code.claude.com/docs/en/agent-sdk/permissions)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for offline boundaries, workspace and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 27 pages and thirteen source-linked UML steps.')
